    <div class="source-table"><table><thead><tr><th>來源</th><th>原始／收錄筆數</th><th>欄位</th><th>覆蓋</th></tr></thead><tbody><tr v-for="s in manifest.sources" :key="s.id"><td><a :href="s.catalog_url" target="_blank" rel="noopener noreferrer">{{ s.label }}</a><small>{{ s.edition }}</small><small>擷取：{{ localDate(s.fetched_at) }}</small></td><td>{{ s.rows }} / {{ s.published_rows }}</td><td>{{ s.columns }}</td><td><strong>100%</strong><small>排除 {{ s.excluded_rows }} 筆</small></td></tr></tbody></table></div>
    <section class="panel"><h2>完整收錄，不等於未公布資料已知</h2><p>{{ manifest.version_note }}</p><p>招生公告、收費證明書內容及學校最新安排仍有各自的發布時間。空白、N.A.、破折號會顯示「來源未提供」；0 保留為 0，不混為未知。</p><p>教學政策是學校提供的陳述，不是平台評分、Banding 或錄取概率。所有日期請以教育局及學校最新公告為準。</p><a href="https://www.chsc.hk/primary" target="_blank" rel="noopener noreferrer">查看家校會最新小學概覽網上版 ↗</a></section>
    <section class="panel"><h2>可下載及重現的資料版本</h2><p>本次資料 ID：<code>{{ manifest.data_id }}</code></p><a class="button" href="/downloads/school-data.zip" download>下載全量來源及整理資料 ZIP</a><p><a href="/downloads/checksums.json">下載檔案 checksum</a> · <a href="/catalog-manifest.json">完整性報告 JSON</a></p><p>原始資料來源及知識產權：教育局、家庭與學校合作事宜委員會。依 DATA.GOV.HK 使用條款整理，本平台非官方服務。</p><a href="https://data.gov.hk/tc/terms-and-conditions" target="_blank" rel="noopener noreferrer">資料使用條款</a></section>
    <section class="panel"><h2>私隱</h2><p>不收集兒童姓名、證件、成績或申請文件。搜尋在瀏覽器處理，私人筆記及進度只儲存在此瀏覽器，沒有分析追蹤程式。載入頁面或資料會產生一般網絡請求；私人筆記不會放入網址或 API。</p><p>清除瀏覽器資料可能令私人清單遺失，請使用匯出備份。跨分頁同時修改會拒絕覆蓋並提示重新整理。</p></section>
   </template>
   <p v-else class="empty">找不到此頁面。<RouterLink to="/">返回首頁</RouterLink></p>
  </template>
 </main><footer class="wrap"><strong>香港選校年鑑</strong><p>官方來源全量整理 · 獨立非官方平台 · 資料以所示來源版本為準</p><RouterLink to="/sources">來源及完整性</RouterLink> · <RouterLink to="/about">私隱</RouterLink></footer>
</template>
<script setup lang="ts">
import {computed,defineComponent,h,onMounted,ref,watch} from 'vue';import {RouterLink,useRoute,useRouter} from 'vue-router';
import SourceFields from './SourceFields.vue';import {levels,readJSON,normalized,safeLink,display,fieldsFor,download,eventICS,type Manifest,type Summary,type School,type Admission} from './catalog';
import {loadNotes,saveNotes,validateNotes,type PrivateState,type Note} from './private';
const route=useRoute(),router=useRouter();const manifest=ref<Manifest|null>(null),index=ref<Summary[]>([]),events=ref<Admission[]>([]);const loading=ref(true),error=ref(''),message=ref(''),saving=ref(false),privateReady=ref(false);const notes=ref<PrivateState>({revision:0,entries:[]});
const query=ref(''),level=ref(''),district=ref(''),funding=ref(''),collection=ref('directory'),year=ref(new Date().getFullYear()+1);const years=[2026,2027,2028,2029,2030];const selected=ref<string[]>([]);const page=computed(()=>Math.max(1,Number(route.query.page)||1));
const school=ref<School|null>(null),detailLoading=ref(false),compared=ref<School[]>([]);let generation=0;
const districts=computed(()=>[...new Set(index.value.map(x=>x.district).filter(Boolean))].sort());const fundings=computed(()=>[...new Set(index.value.map(x=>x.funding).filter(Boolean))].sort());
const filtered=computed(()=>index.value.filter(s=>(!level.value||s.level===level.value)&&(!district.value||s.district===district.value)&&(!funding.value||s.funding===funding.value)&&(collection.value==='all'||collection.value==='annual'&&s.annual_rows>0||collection.value==='directory'&&s.directory_rows>0)&&normalized(s.name+s.english_name+s.address+s.school_numbers.join(' ')).includes(normalized(query.value))));
const sourceRows=computed(()=>filtered.value.reduce((n,s)=>n+(collection.value==='annual'?s.annual_rows:collection.value==='directory'?s.directory_rows:s.annual_rows+s.directory_rows),0));const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/24)));const pageItems=computed(()=>filtered.value.slice((page.value-1)*24,page.value*24));
const source=(id:string)=>manifest.value?.sources.find(s=>s.id===id);const localDate=(s?:string)=>s?new Date(s).toLocaleString('zh-HK',{timeZone:'Asia/Hong_Kong'})+'（香港時間）':'';const schoolURL=(id:string)=>({path:'/schools/'+id,query:{year:String(year.value)}});
const related=computed(()=>school.value?index.value.filter(s=>s.id!==school.value!.id&&s.name===school.value!.name&&s.level===school.value!.level):[]);
const calendarEvents=computed(()=>events.value.filter(e=>(!level.value||e.level===level.value)&&e.entry_year===year.value).sort((a,b)=>a.starts_on.localeCompare(b.starts_on)));
const relatedEvents=computed(()=>!school.value?[]:events.value.filter(e=>e.entry_year===year.value&&e.level===school.value!.level&&(e.school_id?e.school_catalog_ids.includes(school.value!.id):e.level!=='PRIMARY'||['官立','資助'].includes(school.value!.funding))).sort((a,b)=>a.starts_on.localeCompare(b.starts_on)));
const compareLabels=computed(()=>[...new Set(compared.value.flatMap(s=>fieldsFor(s).map(x=>x[0])))]);
const EventCards=defineComponent({props:{events:{type:Array as ()=>Admission[],required:true}},setup:props=>()=>h('div',{class:'events'},props.events.map(e=>h('article',{class:'event',key:e.id},[h('div',{class:'date'},e.starts_on+(e.ends_on?' 至 '+e.ends_on:'')),h('h3',e.title),h('p',e.description),h('p',{class:'muted'},e.applicability),h('a',{href:safeLink(e.source_url)??undefined,target:'_blank',rel:'noopener noreferrer'},'查看原始公告 ↗'),h('small','核對：'+localDate(e.checked_at))])))});
async function record(id:string):Promise<School>{if(!/^school_[a-f0-9]{24}$/.test(id))throw new Error('學校資料編號不正確。');return readJSON<School>('/data/'+manifest.value!.data_id+'/schools/'+id+'.json');}
async function sync(){query.value=typeof route.query.q==='string'?route.query.q:'';level.value=typeof route.query.level==='string'?route.query.level:'';district.value=typeof route.query.district==='string'?route.query.district:'';funding.value=typeof route.query.funding==='string'?route.query.funding:'';collection.value=['annual','all'].includes(String(route.query.collection))?String(route.query.collection):'directory';const y=Number(route.query.year);year.value=years.includes(y)?y:new Date().getFullYear()+1;message.value='';error.value='';const gen=++generation;if(!manifest.value)return;school.value=null;compared.value=[];detailLoading.value=false;try{if(route.path.startsWith('/schools/')){detailLoading.value=true;const s=await record(route.path.split('/')[2]);if(gen===generation)school.value=s;}if(route.path==='/compare'){const ids=String(route.query.ids??'').split(',').filter(Boolean);if(ids.length<2||ids.length>4||new Set(ids).size!==ids.length)throw new Error('請選擇兩至四個不同的同學段資料項目。');const rows=await Promise.all(ids.map(record));if(new Set(rows.map(s=>s.level)).size!==1)throw new Error('請比較相同學段的學校。');if(gen===generation)compared.value=rows;}}catch(e){if(gen===generation)error.value=String(e);}finally{if(gen===generation)detailLoading.value=false;}}
async function reload(){loading.value=true;error.value='';try{const m=await readJSON<Manifest>('/catalog-manifest.json');if(m.environment!=='production'||!/^\w{64}$/.test(m.data_id)||m.coverage_status!=='COMPLETE_SELECTED_OFFICIAL_RESOURCES'||m.sources.length!==4||m.sources.some(s=>s.rows!==s.published_rows||s.excluded_rows!==0))throw new Error('資料版本未通過完整性检查。');manifest.value=m;[index.value,events.value]=await Promise.all([readJSON<Summary[]>('/data/'+m.data_id+'/index.json'),readJSON<Admission[]>('/data/'+m.data_id+'/events.json')]);await sync();}catch(e){error.value=String(e);}finally{loading.value=false;}}
function apply(){void router.replace({path:route.path==='/'?'/schools':route.path,query:{q:query.value||undefined,level:level.value||undefined,district:district.value||undefined,funding:funding.value||undefined,collection:collection.value,year:String(year.value)}});}
function reset(){query.value='';level.value='';district.value='';funding.value='';collection.value='directory';apply();}function setPage(n:number){void router.replace({query:{...route.query,page:String(n)}});}
function toggle(s:Summary){error.value='';if(selected.value.includes(s.id)){selected.value=selected.value.filter(id=>id!==s.id);return;}if(selected.value.length>=4){error.value='最多比較四項。';return;}if(selected.value.length&&index.value.find(x=>x.id===selected.value[0])?.level!==s.level){error.value='請選擇同一學段；先取消其他學段的比較項目。';return;}selected.value.push(s.id);}function openCompare(){void router.push({path:'/compare',query:{ids:selected.value.join(','),year:String(year.value)}});}
async function persist(){if(saving.value)return;saving.value=true;message.value='';try{notes.value=await saveNotes(notes.value);message.value='已儲存於此瀏覽器。';error.value='';}catch(e){error.value=String(e);}finally{saving.value=false;}}
async function addNote(s:School){if(!notes.value.entries.some(n=>n.id===s.id&&n.year===year.value)){notes.value.entries.push({id:s.id,name:s.name,year:year.value,note:'',status:'considering'});await persist();}else message.value='此學校已在私人清單。';}
async function removeNote(n:Note){if(!window.confirm('移除此學年的學校及筆記？'))return;notes.value.entries=notes.value.entries.filter(x=>x!==n);await persist();}
function backup(){download('hk-school-private.json',JSON.stringify({schema:1,entries:notes.value.entries},null,2));}
async function importBackup(e:Event){try{const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;if(file.size>1000000)throw new Error('備份超過1MB。');const payload:unknown=JSON.parse(await file.text());if(!payload||typeof payload!=='object'||!('schema' in payload)||payload.schema!==1||!('entries' in payload))throw new Error('不是本版本私人備份。');const entries=validateNotes(payload.entries);if(!window.confirm('合併 '+entries.length+' 項？相同學校及學年的既有筆記會保留，不會上傳。'))return;const map=new Map(notes.value.entries.map(n=>[n.id+':'+n.year,n]));for(const n of entries)if(!map.has(n.id+':'+n.year))map.set(n.id+':'+n.year,n);notes.value.entries=validateNotes([...map.values()]);await persist();}catch(err){error.value=String(err);}}
function exportICS(items:Admission[]){download('hk-school-admissions.ics',eventICS(items),'text/calendar;charset=utf-8');}
watch(()=>route.fullPath,()=>void sync());onMounted(()=>{void reload();void loadNotes().then(n=>{notes.value=n;privateReady.value=true;}).catch(e=>{error.value=String(e);});});
</script>
